            migrationBuilder.UpdateData(
                table: "HeroSlides",
                keyColumn: "Id",
                keyValue: new Guid("00000000-0000-0000-0000-000000000101"),
                columns: new[] { "InstructionTooltips", "PriceTexts", "Subtexts", "Titles" },
                values: new object[] { "{\"en\":\"50% discount applies automatically to all functional prints in Black or White PETG.\",\"nl\":\"50% korting wordt automatisch verrekend bij selectie van zwart of wit PETG.\",\"tr\":\"Siyah veya Beyaz PETG\\u0027deki t\\u00FCm fonksiyonel bask\\u0131lara %50 indirim otomatik olarak uygulan\\u0131r.\",\"ru\":\"\\u0421\\u043A\\u0438\\u0434\\u043A\\u0430 50% \\u0430\\u0432\\u0442\\u043E\\u043C\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043A\\u0438 \\u043F\\u0440\\u0438\\u043C\\u0435\\u043D\\u044F\\u0435\\u0442\\u0441\\u044F \\u043A\\u043E \\u0432\\u0441\\u0435\\u043C \\u0444\\u0443\\u043D\\u043A\\u0446\\u0438\\u043E\\u043D\\u0430\\u043B\\u044C\\u043D\\u044B\\u043C \\u0434\\u0435\\u0442\\u0430\\u043B\\u044F\\u043C \\u0438\\u0437 \\u0447\\u0435\\u0440\\u043D\\u043E\\u0433\\u043E \\u0438\\u043B\\u0438 \\u0431\\u0435\\u043B\\u043E\\u0433\\u043E PETG.\",\"ar\":\"\\u064A\\u0646\\u0637\\u0628\\u0642 \\u062E\\u0635\\u0645 50% \\u062A\\u0644\\u0642\\u0627\\u0626\\u064A\\u064B\\u0627 \\u0639\\u0644\\u0649 \\u062C\\u0645\\u064A\\u0639 \\u0627\\u0644\\u0645\\u0637\\u0628\\u0648\\u0639\\u0627\\u062A \\u0627\\u0644\\u0648\\u0638\\u064A\\u0641\\u064A\\u0629 \\u0628\\u0627\\u0644\\u0644\\u0648\\u0646\\u064A\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0648\\u062F \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0628\\u064A\\u0636 \\u0645\\u0646 \\u062E\\u0627\\u0645\\u0629 PETG.\"}", "{\"en\":\"50% Off Black \\u0026 White PETG\",\"nl\":\"50% Korting op PETG\",\"tr\":\"PETG\\u0027de %50 \\u0130ndirim\",\"ru\":\"\\u0421\\u043A\\u0438\\u0434\\u043A\\u0430 50% \\u043D\\u0430 PETG\",\"ar\":\"\\u062E\\u0635\\u0645 50% \\u0639\\u0644\\u0649 PETG\"}", "{\"en\":\"Special promotion: Get an automatic 50% discount on all custom 3D prints ordered in high-durability Black or White PETG. UV-resistant, impact-proof, and heat tolerant.\",\"nl\":\"Speciale actie: Profiteer van 50% korting op alle 3D-prints in oersterk zwart of wit PETG. Weerbestendig, slagvast en hittebestendig.\",\"tr\":\"\\u00D6zel promosyon: Y\\u00FCksek dayan\\u0131ml\\u0131 Siyah veya Beyaz PETG ile sipari\\u015F edilen t\\u00FCm \\u00F6zel 3D bask\\u0131larda otomatik %50 indirim. UV \\u0131\\u015F\\u0131nlar\\u0131na, darbelere ve \\u0131s\\u0131ya dayan\\u0131kl\\u0131d\\u0131r.\",\"ru\":\"\\u0421\\u043F\\u0435\\u0446\\u0438\\u0430\\u043B\\u044C\\u043D\\u0430\\u044F \\u0430\\u043A\\u0446\\u0438\\u044F: \\u0430\\u0432\\u0442\\u043E\\u043C\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043A\\u0430\\u044F \\u0441\\u043A\\u0438\\u0434\\u043A\\u0430 50% \\u043D\\u0430 \\u0432\\u0441\\u0435 \\u0438\\u043D\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043B\\u044C\\u043D\\u044B\\u0435 3D-\\u043E\\u0442\\u043F\\u0435\\u0447\\u0430\\u0442\\u043A\\u0438 \\u0438\\u0437 \\u043F\\u0440\\u043E\\u0447\\u043D\\u043E\\u0433\\u043E \\u0447\\u0435\\u0440\\u043D\\u043E\\u0433\\u043E \\u0438\\u043B\\u0438 \\u0431\\u0435\\u043B\\u043E\\u0433\\u043E PETG. \\u0423\\u0441\\u0442\\u043E\\u0439\\u0447\\u0438\\u0432 \\u043A \\u0423\\u0424, \\u0443\\u0434\\u0430\\u0440\\u0430\\u043C \\u0438 \\u043F\\u0435\\u0440\\u0435\\u043F\\u0430\\u0434\\u0430\\u043C \\u0442\\u0435\\u043C\\u043F\\u0435\\u0440\\u0430\\u0442\\u0443\\u0440.\",\"ar\":\"\\u0639\\u0631\\u0636 \\u062E\\u0627\\u0635: \\u0627\\u062D\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u062E\\u0635\\u0645 \\u062A\\u0644\\u0642\\u0627\\u0626\\u064A \\u0628\\u0646\\u0633\\u0628\\u0629 50% \\u0639\\u0644\\u0649 \\u062C\\u0645\\u064A\\u0639 \\u0627\\u0644\\u0645\\u0637\\u0628\\u0648\\u0639\\u0627\\u062A \\u062B\\u0644\\u0627\\u062B\\u064A\\u0629 \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062F \\u0627\\u0644\\u0645\\u0635\\u0646\\u0648\\u0639\\u0629 \\u0645\\u0646 \\u062E\\u064A\\u0648\\u0637 PETG \\u0627\\u0644\\u0645\\u062A\\u064A\\u0646\\u0629 \\u0628\\u0627\\u0644\\u0644\\u0648\\u0646\\u064A\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0648\\u062F \\u0623\\u0648 \\u0627\\u0644\\u0623\\u0628\\u064A\\u0636. \\u0645\\u0642\\u0627\\u0648\\u0645 \\u0644\\u0644\\u0623\\u0634\\u0639\\u0629 \\u0641\\u0648\\u0642 \\u0627\\u0644\\u0628\\u0646\\u0641\\u0633\\u062C\\u064A\\u0629 \\u0648\\u0627\\u0644\\u0635\\u062F\\u0645\\u0627\\u062A \\u0648\\u0627\\u0644\\u062D\\u0631\\u0627\\u0631\\u0629.\"}", "{\"en\":\"50% Off Black \\u0026 White PETG Prints\",\"nl\":\"50% Korting op Zwart \\u0026 Wit PETG Prints\",\"tr\":\"Siyah ve Beyaz PETG Bask\\u0131larda %50 \\u0130ndirim\",\"ru\":\"\\u0421\\u043A\\u0438\\u0434\\u043A\\u0430 50% \\u043D\\u0430 \\u043F\\u0435\\u0447\\u0430\\u0442\\u044C \\u0438\\u0437 \\u0447\\u0435\\u0440\\u043D\\u043E\\u0433\\u043E \\u0438 \\u0431\\u0435\\u043B\\u043E\\u0433\\u043E PETG\",\"ar\":\"\\u062E\\u0635\\u0645 50% \\u0639\\u0644\\u0649 \\u0637\\u0628\\u0627\\u0639\\u0629 PETG \\u0628\\u0627\\u0644\\u0644\\u0648\\u0646\\u064A\\u0646 \\u0627\\u0644\\u0623\\u0633\\u0648\\u062F \\u0648\\u0627\\u0644\\u0623\\u0628\\u064A\\u0636\"}" });

            migrationBuilder.UpdateData(
                table: "HeroSlides",
                keyColumn: "Id",
                keyValue: new Guid("00000000-0000-0000-0000-000000000102"),
                columns: new[] { "InstructionTooltips", "PriceTexts", "Subtexts", "Titles" },
                values: new object[] { "{\"en\":\"Drop any picture in our configurator for an instant 3D relief preview with color swaps.\",\"nl\":\"Sleep je afbeelding in onze configurator voor een directe full-color 3D reli\\u00EBf weergave.\",\"tr\":\"Renk ge\\u00E7i\\u015Fleriyle an\\u0131nda 3D r\\u00F6lyef \\u00F6nizlemesi i\\u00E7in herhangi bir resmi konfig\\u00FCrat\\u00F6r\\u00FCm\\u00FCze b\\u0131rak\\u0131n.\",\"ru\":\"\\u041F\\u0435\\u0440\\u0435\\u0442\\u0430\\u0449\\u0438\\u0442\\u0435 \\u0438\\u0437\\u043E\\u0431\\u0440\\u0430\\u0436\\u0435\\u043D\\u0438\\u0435 \\u0432 \\u043A\\u043E\\u043D\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0442\\u043E\\u0440 \\u0434\\u043B\\u044F \\u043C\\u0433\\u043D\\u043E\\u0432\\u0435\\u043D\\u043D\\u043E\\u0433\\u043E \\u043F\\u0440\\u0435\\u0434\\u043F\\u0440\\u043E\\u0441\\u043C\\u043E\\u0442\\u0440\\u0430 3D-\\u0440\\u0435\\u043B\\u044C\\u0435\\u0444\\u0430 \\u0441\\u043E \\u0441\\u043C\\u0435\\u043D\\u043E\\u0439 \\u0446\\u0432\\u0435\\u0442\\u043E\\u0432.\",\"ar\":\"\\u0642\\u0645 \\u0628\\u0633\\u062D\\u0628 \\u0623\\u064A \\u0635\\u0648\\u0631\\u0629 \\u0625\\u0644\\u0649 \\u0623\\u062F\\u0627\\u062A\\u0646\\u0627 \\u0644\\u0644\\u062D\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0639\\u0627\\u064A\\u0646\\u0629 \\u0641\\u0648\\u0631\\u064A\\u0629 \\u0644\\u0644\\u0648\\u062D\\u0629 \\u0627\\u0644\\u0628\\u0627\\u0631\\u0632\\u0629 \\u062B\\u0644\\u0627\\u062B\\u064A\\u0629 \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062F.\"}", "{\"en\":\"From \\u20AC14.95 / Painting\",\"nl\":\"Vanaf \\u20AC14,95 / Schilderij\",\"tr\":\"Tablo Ba\\u015F\\u0131na \\u20AC14,95\\u0027ten Ba\\u015Flayan Fiyatlarla\",\"ru\":\"\\u041E\\u0442 \\u20AC14.95 / \\u043A\\u0430\\u0440\\u0442\\u0438\\u043D\\u0430\",\"ar\":\"\\u0627\\u0628\\u062A\\u062F\\u0627\\u0621\\u064B \\u0645\\u0646 \\u20AC14.95 / \\u0644\\u0648\\u062D\\u0629\"}", "{\"en\":\"Upload any photo or illustration to transform it into a vibrant, multi-color 3D relief print using optical layer blending. No painting required!\",\"nl\":\"Upload een 2D foto of illustratie en verander deze in een tactiel, meerkleurig 3D reli\\u00EBf schilderij met optische laagmenging.\",\"tr\":\"Optik katman harmanlama kullanarak herhangi bir foto\\u011Fraf\\u0131 veya \\u00E7izimi canl\\u0131, \\u00E7ok renkli bir 3D kabartma bask\\u0131ya d\\u00F6n\\u00FC\\u015Ft\\u00FCr\\u00FCn. Boyama gerekmez!\",\"ru\":\"\\u0417\\u0430\\u0433\\u0440\\u0443\\u0437\\u0438\\u0442\\u0435 \\u043B\\u044E\\u0431\\u0443\\u044E \\u0444\\u043E\\u0442\\u043E\\u0433\\u0440\\u0430\\u0444\\u0438\\u044E \\u0438\\u043B\\u0438 \\u0438\\u043B\\u043B\\u044E\\u0441\\u0442\\u0440\\u0430\\u0446\\u0438\\u044E, \\u0447\\u0442\\u043E\\u0431\\u044B \\u043F\\u0440\\u0435\\u0432\\u0440\\u0430\\u0442\\u0438\\u0442\\u044C \\u0435\\u0435 \\u0432 \\u044F\\u0440\\u043A\\u0443\\u044E \\u043C\\u043D\\u043E\\u0433\\u043E\\u0446\\u0432\\u0435\\u0442\\u043D\\u0443\\u044E 3D-\\u0440\\u0435\\u043B\\u044C\\u0435\\u0444\\u043D\\u0443\\u044E \\u043A\\u0430\\u0440\\u0442\\u0438\\u043D\\u0443 \\u0441 \\u043F\\u043E\\u043C\\u043E\\u0449\\u044C\\u044E \\u043E\\u043F\\u0442\\u0438\\u0447\\u0435\\u0441\\u043A\\u043E\\u0433\\u043E \\u0441\\u043C\\u0435\\u0448\\u0438\\u0432\\u0430\\u043D\\u0438\\u044F \\u0441\\u043B\\u043E\\u0435\\u0432.\",\"ar\":\"\\u0627\\u0631\\u0641\\u0639 \\u0623\\u064A \\u0635\\u0648\\u0631\\u0629 \\u0623\\u0648 \\u0631\\u0633\\u0645 \\u062A\\u0648\\u0636\\u064A\\u062D\\u064A \\u0644\\u062A\\u062D\\u0648\\u064A\\u0644\\u0647 \\u0625\\u0644\\u0649 \\u0644\\u0648\\u062D\\u0629 \\u0628\\u0627\\u0631\\u0632\\u0629 \\u062B\\u0644\\u0627\\u062B\\u064A\\u0629 \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062F \\u0645\\u062A\\u0639\\u062F\\u062F\\u0629 \\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u0646 \\u0628\\u0627\\u0633\\u062A\\u062E\\u062F\\u0627\\u0645 \\u0645\\u0632\\u062C \\u0627\\u0644\\u0637\\u0628\\u0642\\u0627\\u062A \\u0627\\u0644\\u0628\\u0635\\u0631\\u064A. \\u0628\\u062F\\u0648\\u0646 \\u0627\\u0644\\u062D\\u0627\\u062C\\u0629 \\u0625\\u0644\\u0649 \\u0637\\u0644\\u0627\\u0621 \\u064A\\u062F\\u0648\\u064A!\"}", "{\"en\":\"HueForge Filament Painting: Turn Pictures into 3D Art\",\"nl\":\"HueForge Filament Painting: Maak van je Foto 3D Kunst\",\"tr\":\"HueForge Filament Tablosu: Resimleri 3D Sanata D\\u00F6n\\u00FC\\u015Ft\\u00FCr\\u00FCn\",\"ru\":\"HueForge Filament Painting: \\u043F\\u0440\\u0435\\u0432\\u0440\\u0430\\u0442\\u0438\\u0442\\u0435 \\u043A\\u0430\\u0440\\u0442\\u0438\\u043D\\u044B \\u0432 3D-\\u0430\\u0440\\u0442\",\"ar\":\"\\u0644\\u0648\\u062D\\u0627\\u062A \\u062E\\u064A\\u0648\\u0637 HueForge: \\u062D\\u0648\\u0651\\u0644 \\u0635\\u0648\\u0631\\u0643 \\u0625\\u0644\\u0649 \\u0641\\u0646 \\u062B\\u0644\\u0627\\u062B\\u064A \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062F\"}" });

