                values: new object[] { "{\"en\":\"Interactive 3D model: drag to rotate 360\\u00B0, scroll to zoom in and inspect geometry.\",\"nl\":\"Interactief 3D-model: sleep om 360\\u00B0 te draaien, scroll om in te zoomen op details.\",\"tr\":\"Etkile\\u015Fimli 3D model: 360\\u00B0 d\\u00F6nd\\u00FCrmek i\\u00E7in s\\u00FCr\\u00FCkleyin, yak\\u0131nla\\u015Ft\\u0131rmak ve geometriyi incelemek i\\u00E7in kayd\\u0131r\\u0131n.\",\"ru\":\"\\u0418\\u043D\\u0442\\u0435\\u0440\\u0430\\u043A\\u0442\\u0438\\u0432\\u043D\\u0430\\u044F 3D-\\u043C\\u043E\\u0434\\u0435\\u043B\\u044C: \\u043F\\u0435\\u0440\\u0435\\u0442\\u0430\\u0441\\u043A\\u0438\\u0432\\u0430\\u0439\\u0442\\u0435 \\u0434\\u043B\\u044F \\u043F\\u043E\\u0432\\u043E\\u0440\\u043E\\u0442\\u0430 \\u043D\\u0430 360\\u00B0, \\u043C\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0438\\u0440\\u0443\\u0439\\u0442\\u0435 \\u0434\\u043B\\u044F \\u043E\\u0441\\u043C\\u043E\\u0442\\u0440\\u0430 \\u0433\\u0435\\u043E\\u043C\\u0435\\u0442\\u0440\\u0438\\u0438.\",\"ar\":\"\\u0646\\u0645\\u0648\\u0630\\u062C \\u062A\\u0641\\u0627\\u0639\\u0644\\u064A \\u062B\\u0644\\u0627\\u062B\\u064A \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062F: \\u0627\\u0633\\u062D\\u0628 \\u0644\\u0644\\u062A\\u062F\\u0648\\u064A\\u0631 \\u0628\\u0632\\u0627\\u0648\\u064A\\u0629 360 \\u062F\\u0631\\u062C\\u0629\\u060C \\u0648\\u0645\\u0631\\u0631 \\u0644\\u0644\\u062A\\u0643\\u0628\\u064A\\u0631 \\u0648\\u0641\\u062D\\u0635 \\u0627\\u0644\\u062A\\u0641\\u0627\\u0635\\u064A\\u0644.\"}", "{\"en\":\"Starting from \\u20AC9.95\",\"nl\":\"Vanaf \\u20AC9,95\",\"tr\":\"\\u20AC9,95\\u0027ten Ba\\u015Flayan Fiyatlarla\",\"ru\":\"\\u041E\\u0442 \\u20AC9.95\",\"ar\":\"\\u0627\\u0628\\u062A\\u062F\\u0627\\u0621\\u064B \\u0645\\u0646 \\u20AC9.95\"}", "{\"en\":\"High-precision FDM 3D printing for functional prototypes, replacement parts, and custom enclosures in 2-5 working days.\",\"nl\":\"Precisie FDM 3D-printen voor functionele prototypes, vervangende onderdelen en behuizingen binnen 2-5 werkdagen.\",\"tr\":\"Fonksiyonel prototipler, yedek par\\u00E7alar ve \\u00F6zel muhafazalar i\\u00E7in 2-5 i\\u015F g\\u00FCn\\u00FC i\\u00E7inde y\\u00FCksek hassasiyetli FDM 3D bask\\u0131.\",\"ru\":\"\\u0412\\u044B\\u0441\\u043E\\u043A\\u043E\\u0442\\u043E\\u0447\\u043D\\u0430\\u044F FDM 3D-\\u043F\\u0435\\u0447\\u0430\\u0442\\u044C \\u0434\\u043B\\u044F \\u0444\\u0443\\u043D\\u043A\\u0446\\u0438\\u043E\\u043D\\u0430\\u043B\\u044C\\u043D\\u044B\\u0445 \\u043F\\u0440\\u043E\\u0442\\u043E\\u0442\\u0438\\u043F\\u043E\\u0432, \\u0437\\u0430\\u043F\\u0430\\u0441\\u043D\\u044B\\u0445 \\u0447\\u0430\\u0441\\u0442\\u0435\\u0439 \\u0438 \\u043A\\u043E\\u0440\\u043F\\u0443\\u0441\\u043E\\u0432 \\u0437\\u0430 2\\u20135 \\u0440\\u0430\\u0431\\u043E\\u0447\\u0438\\u0445 \\u0434\\u043D\\u0435\\u0439.\",\"ar\":\"\\u0637\\u0628\\u0627\\u0639\\u0629 \\u062B\\u0644\\u0627\\u062B\\u064A\\u0629 \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062F \\u0639\\u0627\\u0644\\u064A\\u0629 \\u0627\\u0644\\u062F\\u0642\\u0629 \\u0628\\u062A\\u0642\\u0646\\u064A\\u0629 FDM \\u0644\\u0644\\u0646\\u0645\\u0627\\u0630\\u062C \\u0627\\u0644\\u0623\\u0648\\u0644\\u064A\\u0629 \\u0627\\u0644\\u0648\\u0638\\u064A\\u0641\\u064A\\u0629 \\u0648\\u0642\\u0637\\u0639 \\u0627\\u0644\\u063A\\u064A\\u0627\\u0631 \\u0648\\u0627\\u0644\\u062D\\u0627\\u0641\\u0638\\u0627\\u062A \\u0627\\u0644\\u0645\\u062E\\u0635\\u0635\\u0629 \\u062E\\u0644\\u0627\\u0644 2-5 \\u0623\\u064A\\u0627\\u0645 \\u0639\\u0645\\u0644.\"}", "{\"en\":\"Rapid Prototyping \\u0026 Custom Parts\",\"nl\":\"Snelle Prototyping \\u0026 Maatwerk Onderdelen\",\"tr\":\"H\\u0131zl\\u0131 Prototipleme ve \\u00D6zel Par\\u00E7alar\",\"ru\":\"\\u0411\\u044B\\u0441\\u0442\\u0440\\u043E\\u0435 \\u043F\\u0440\\u043E\\u0442\\u043E\\u0442\\u0438\\u043F\\u0438\\u0440\\u043E\\u0432\\u0430\\u043D\\u0438\\u0435 \\u0438 \\u0434\\u0435\\u0442\\u0430\\u043B\\u0438 \\u043D\\u0430 \\u0437\\u0430\\u043A\\u0430\\u0437\",\"ar\":\"\\u0627\\